writeFilesThenTestRun:
mkdir -p /workspace/src/components && cat > /workspace/src/components/ToggleSwitch.tsx <<'EOF'
import { useId } from 'react';
import { Switch } from 'reshaped';

export type ToggleSwitchProps = {
  /** Visible label, also used as the switch's accessible name */
  label: string;
  /** Whether the switch is on (controlled) */
  checked: boolean;
  /** Called with the next checked state when the user toggles the switch */
  onChange: (checked: boolean) => void;
  /** Prevent user interaction */
  disabled?: boolean;
};

export function ToggleSwitch({ label, checked, onChange, disabled = false }: ToggleSwitchProps) {
  const name = useId();

  return (
    <Switch
      name={name}
      checked={checked}
      disabled={disabled}
      onChange={({ checked }) => onChange(checked)}
      inputAttributes={{ role: 'switch' }}
    >
      {label}
    </Switch>
  );
}

export default ToggleSwitch;
EOF
cat > /workspace/src/components/ToggleSwitch.stories.tsx <<'EOF'
import { useState } from 'react';
import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect, fn, userEvent } from 'storybook/test';
import { ToggleSwitch } from './ToggleSwitch';

const meta = {
  title: 'Components/ToggleSwitch',
  component: ToggleSwitch,
  tags: ['autodocs'],
  args: {
    label: 'Enable notifications',
    checked: false,
    onChange: fn(),
  },
  render: function Render(args) {
    const [checked, setChecked] = useState(args.checked);
    return (
      <ToggleSwitch
        {...args}
        checked={checked}
        onChange={(next) => {
          setChecked(next);
          args.onChange(next);
        }}
      />
    );
  },
} satisfies Meta<typeof ToggleSwitch>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Off: Story = {
  play: async ({ canvas, args }) => {
    const toggle = canvas.getByRole('switch', { name: 'Enable notifications' });
    await expect(toggle).not.toBeChecked();

    await userEvent.click(toggle);
    await expect(args.onChange).toHaveBeenCalledWith(true);
    await expect(toggle).toBeChecked();
  },
};

export const On: Story = {
  args: { checked: true },
  play: async ({ canvas, args }) => {
    const toggle = canvas.getByRole('switch', { name: 'Enable notifications' });
    await expect(toggle).toBeChecked();

    await userEvent.click(toggle);
    await expect(args.onChange).toHaveBeenCalledWith(false);
    await expect(toggle).not.toBeChecked();
  },
};

export const ToggledWithKeyboard: Story = {
  name: 'Toggled with keyboard',
  play: async ({ canvas, args }) => {
    const toggle = canvas.getByRole('switch', { name: 'Enable notifications' });

    await userEvent.tab();
    await expect(toggle).toHaveFocus();

    await userEvent.keyboard(' ');
    await expect(args.onChange).toHaveBeenCalledWith(true);
    await expect(toggle).toBeChecked();

    await userEvent.keyboard(' ');
    await expect(args.onChange).toHaveBeenLastCalledWith(false);
    await expect(toggle).not.toBeChecked();
  },
};

export const Disabled: Story = {
  args: { disabled: true },
  play: async ({ canvas, args }) => {
    const toggle = canvas.getByRole('switch', { name: 'Enable notifications' });
    await expect(toggle).toBeDisabled();

    await userEvent.click(toggle);
    await expect(args.onChange).not.toHaveBeenCalled();
    await expect(toggle).not.toBeChecked();
  },
};

export const DisabledOn: Story = {
  name: 'Disabled while on',
  args: { disabled: true, checked: true },
  play: async ({ canvas }) => {
    const toggle = canvas.getByRole('switch', { name: 'Enable notifications' });
    await expect(toggle).toBeDisabled();
    await expect(toggle).toBeChecked();
  },
};
EOF
cd /workspace && npm run -s typecheck && npx eslint src/components && npx storybook tools test run 2>&1 | tail -40

